# %% ../nbs/02_Evaluation/00_Backtesting.ipynb #ce34fd4d
import json
import re
import time
from pathlib import Path
from typing import Callable

import numpy as np
import pandas as pd

# %% ../nbs/02_Evaluation/00_Backtesting.ipynb #385dc152
HORIZON = 24
SEASON = 24
N_WINDOWS = 30
STEP = 5 * 24


def origins(index: pd.DatetimeIndex, horizon: int = HORIZON, n_windows: int = N_WINDOWS, step: int = STEP) -> list[int]:
    "Positions of the forecast origins: `n_windows` midnights `step` apart, the last one at least `horizon` before the end."
    last = len(index) - horizon
    while index[last].hour != 0:
        last -= 1
    first = last - (n_windows - 1) * step
    if first <= 0:
        raise ValueError("series too short for this many windows")
    return list(range(first, last + 1, step))

# %% ../nbs/02_Evaluation/00_Backtesting.ipynb #2680540d
Forecaster = Callable[[pd.Series, int], np.ndarray]


def future_index(history: pd.Series, horizon: int) -> pd.DatetimeIndex:
    "The `horizon` timestamps after the end of `history`."
    freq = history.index.freq or pd.infer_freq(history.index[-5:])
    return pd.date_range(history.index[-1], periods=horizon + 1, freq=freq)[1:]


def backtest(y: pd.Series, forecaster: Forecaster, horizon: int = HORIZON,
             n_windows: int = N_WINDOWS, step: int = STEP) -> pd.DataFrame:
    "Rolling-origin backtest: one row per (window, forecast hour) with `y` and `yhat`. Total seconds in `.attrs`."
    rows, seconds = [], 0.0
    for w, o in enumerate(origins(y.index, horizon, n_windows, step)):
        t0 = time.perf_counter()
        yhat = np.asarray(forecaster(y.iloc[:o], horizon), dtype=float).reshape(-1)
        seconds += time.perf_counter() - t0
        if len(yhat) != horizon:
            raise ValueError(f"forecaster returned {len(yhat)} values, expected {horizon}")
        actual = y.iloc[o:o + horizon]
        rows.append(pd.DataFrame({"window": w, "origin": y.index[o], "ds": actual.index,
                                  "step": np.arange(1, horizon + 1), "y": actual.to_numpy(), "yhat": yhat}))
    out = pd.concat(rows, ignore_index=True)
    out.attrs |= {"seconds": seconds, "horizon": horizon, "n_windows": n_windows, "step": step}
    return out

# %% ../nbs/02_Evaluation/00_Backtesting.ipynb #8df47504
def seasonal_naive(m: int = SEASON) -> Forecaster:
    "Forecaster that repeats the last `m` observations."
    def f(history: pd.Series, horizon: int) -> np.ndarray:
        last = history.to_numpy()[-m:]
        return np.resize(last, horizon)
    f.__name__ = f"seasonal_naive_{m}"
    return f

# %% ../nbs/02_Evaluation/00_Backtesting.ipynb #20e88f5e
def mae(y, yhat) -> float:
    "Mean absolute error."
    return float(np.mean(np.abs(np.asarray(y) - np.asarray(yhat))))


def rmse(y, yhat) -> float:
    "Root mean squared error."
    return float(np.sqrt(np.mean((np.asarray(y) - np.asarray(yhat)) ** 2)))


def wape(y, yhat) -> float:
    "Weighted absolute percentage error: total absolute error over total actual."
    y = np.asarray(y)
    return float(np.sum(np.abs(y - np.asarray(yhat))) / np.sum(np.abs(y)))


def mape(y, yhat) -> float:
    "Mean absolute percentage error; infinite when any actual is 0."
    y, yhat = np.asarray(y, dtype=float), np.asarray(yhat, dtype=float)
    if np.any(y == 0):
        return float("inf")
    return float(np.mean(np.abs(y - yhat) / np.abs(y)))


def smape(y, yhat) -> float:
    "Symmetric MAPE in [0, 2]; a 0/0 term counts as 0."
    y, yhat = np.asarray(y, dtype=float), np.asarray(yhat, dtype=float)
    den = np.abs(y) + np.abs(yhat)
    with np.errstate(divide="ignore", invalid="ignore"):
        t = np.where(den == 0, 0.0, 2 * np.abs(y - yhat) / den)
    return float(np.mean(t))


def mase_scale(y: pd.Series, m: int = SEASON) -> pd.Series:
    "For each position, the in-sample seasonal naive MAE of everything before it."
    d = (y - y.shift(m)).abs()
    return d.expanding().mean().shift(1)


def score(bt: pd.DataFrame, y: pd.Series, m: int = SEASON, exclude: pd.Series | None = None) -> dict:
    "MAE, RMSE, WAPE, sMAPE, MASE and skill against seasonal naive; rows where `exclude` is True are not scored."
    scale = mase_scale(y, m)
    ref = backtest(y, seasonal_naive(m), **{k: bt.attrs[k] for k in ("horizon", "n_windows", "step")})
    if exclude is not None:
        keep = ~exclude.reindex(bt.ds).fillna(False).to_numpy(bool)
        bt, ref = bt[keep], ref[keep]
    per_window = bt.groupby("window").apply(
        lambda g: mae(g.y, g.yhat) / scale.loc[g.origin.iloc[0]], include_groups=False)
    return {"mase": float(per_window.mean()), "skill": 1 - mae(bt.y, bt.yhat) / mae(ref.y, ref.yhat),
            "mae": mae(bt.y, bt.yhat), "rmse": rmse(bt.y, bt.yhat), "wape": wape(bt.y, bt.yhat),
            "smape": smape(bt.y, bt.yhat), "seconds": bt.attrs.get("seconds", float("nan"))}

# %% ../nbs/02_Evaluation/00_Backtesting.ipynb #d7633f9a
def results_dir() -> Path:
    "The `results` folder next to `nbdev.yml`, found by walking up from the working directory."
    here = Path.cwd().resolve()
    for d in [here, *here.parents]:
        if (d / "nbdev.yml").exists():
            r = d / "results"
            r.mkdir(exist_ok=True)
            return r
    raise FileNotFoundError("no nbdev.yml above the working directory")


def record(model: str, family: str, scores: dict, notebook: str, dataset: str = "household", notes: str = "") -> dict:
    "Write one scoreboard row to `results/<dataset>_<model>.json` and return it."
    slug = re.sub(r"[^a-z0-9]+", "_", f"{dataset} {model}".lower()).strip("_")
    rec = {"model": model, "family": family, "dataset": dataset, "notebook": notebook, "notes": notes}
    rec |= {k: (round(v, 4) if k != "seconds" else round(v, 1)) for k, v in scores.items()}
    (results_dir() / f"{slug}.json").write_text(json.dumps(rec, indent=1) + "\n")
    return rec


def load_results() -> pd.DataFrame:
    "All scoreboard rows, best MASE first within each dataset."
    rows = [json.loads(p.read_text()) for p in sorted(results_dir().glob("*.json"))]
    return pd.DataFrame(rows).sort_values(["dataset", "mase"], ignore_index=True)
